// @ts-check
// `@type` JSDoc annotations allow editor autocompletion and type checking
// (when paired with `@ts-check`).
// There are various equivalent ways to declare your Docusaurus config.
// See: https://docusaurus.io/docs/api/docusaurus-config

import { themes as prismThemes } from "prism-react-renderer";
import { readFileSync } from "node:fs";
import { currentVersion, previewVersion } from "./version-config.js";

const releasedVersions = JSON.parse(readFileSync(new URL("./versions.json", import.meta.url), "utf8"));
const hasCurrentVersion = releasedVersions.includes(currentVersion);

/** @type {import('@docusaurus/types').Config} */
const config = {
  title: "Maester",
  tagline: "Your Microsoft Security test automation framework!",
  favicon: "img/favicon.ico",

  // Set the production url of your site here
  url: "https://maester.dev",
  // Set the /<baseUrl>/ pathname under which your site is served
  // For GitHub pages deployment, it is often '/<projectName>/'
  baseUrl: "/",

  // GitHub pages deployment config.
  // If you aren't using GitHub pages, you don't need these.
  organizationName: "maester365", // Usually your GitHub org/user name.
  projectName: "maester", // Usually your repo name.

  onBrokenLinks: "throw",
  // onBrokenMarkdownLinks: "warn", // Deprecated and moved to markdown.hooks.onBrokenMarkdownLinks

  // Even if you don't use internationalization, you can use this field to set
  // useful metadata like html lang. For example, if your site is Chinese, you
  // may want to replace "en" with "zh-Hans".
  i18n: {
    defaultLocale: "en",
    locales: ["en"],
  },

  markdown: {
    mermaid: true,
    hooks: {
      onBrokenMarkdownLinks: 'warn',
    },
  },
  themes: [
    "@docusaurus/theme-mermaid",
    "@easyops-cn/docusaurus-search-local",
  ],

  plugins: [
    "./src/plugins/contributor-pages.js",
    [
      "posthog-docusaurus",
      {
        apiKey: "REDACTED",
        appUrl: "https://us.i.posthog.com", // optional, defaults to "https://us.i.posthog.com"
        enableInDevelopment: false, // optional
      },
    ],
  ],

  presets: [
    [
      "classic",
      /** @type {import('@docusaurus/preset-classic').Options} */
      ({
        docs: {
          sidebarPath: "./sidebars.js",
          editUrl: "https://github.com/maester365/maester/tree/main/website",
          lastVersion: hasCurrentVersion ? currentVersion : 'current',
          versions: {
            current: {
              label: previewVersion,
              banner: 'unreleased',
              badge: true,
            },
            ...(hasCurrentVersion ? { [currentVersion]: {
              label: currentVersion,
              path: '/',
              banner: 'none',
              badge: true,
            } } : {}),
            // Example of unmaintained / deprecated versions.
            //'1.2.0': {
            //  banner: 'unmaintained',
            //}
          },
        },
        blog: {
          blogSidebarTitle: 'All posts',
          blogSidebarCount: 0,
          postsPerPage: 13,
        },
        theme: {
          customCss: "./src/css/custom.css",
        },
        googleTagManager: {
          containerId: 'GTM-TXV8GGWT',
        },
        gtag: {
          trackingID: 'G-LKBLBBCLH0',
          anonymizeIP: true,
        },
      }),
    ],
  ],

  themeConfig:
    /** @type {import('@docusaurus/preset-classic').ThemeConfig} */
    ({
      // Replace with your project's social card
      image: "img/maester-social-card.jpg",
      navbar: {
        title: "Maester",
        logo: {
          alt: "Maester Logo",
          src: "img/logo.svg",
        },
        items: [
          {
            type: 'docsVersionDropdown',
            position: 'left',
            dropdownActiveClassDisabled: true, // Recommended for clear separation.
          },
          {
            type: "docSidebar",
            sidebarId: "docsSidebar",
            position: "left",
            label: "Docs",
          },
          {
            type: "docSidebar",
            sidebarId: "testsSidebar",
            position: "left",
            label: "Tests",
          },
          {
            type: "docSidebar",
            sidebarId: "commandsSidebar",
            position: "left",
            label: "Commands",
          },
          { to: 'manifesto', label: 'Manifesto', position: 'left' },
          { to: 'contributors', label: 'Contributors', position: 'left' },
          { to: 'blog', label: 'Blog', position: 'left' },
          { href: 'https://packs.maester.cloud', label: 'Packs', position: 'left' },
          { to: 'sponsor', label: 'Sponsor', position: 'right', className: 'navbar--sponsor-link' },
          {
            "aria-label": "GitHub Repository",
            className: "navbar--github-link",
            href: "https://github.com/maester365/maester",
            position: "right",
          },
          {
            to: '/docs/installation',
            label: 'Install',
            position: 'right',
            className: 'navbar--install-cta',
          },
        ],
      },
      footer: {
        style: "dark",
        links: [
          {
            title: "Docs",
            items: [
              {
                label: "Tests",
                to: "/docs/intro",
              },
              {
                label: "Manifesto",
                to: "/manifesto",
              },
            ],
          },
          {
            title: "Community",
            items: [
              {
                label: "Sponsor",
                to: "/sponsor",
              },
              {
                label: "Contributors",
                to: "/contributors",
              },
              {
                label: "Discord",
                href: "https://discord.maester.dev/",
              },
              {
                label: "Twitter",
                href: "https://twitter.com/maester365",
              },
            ],
          },
          {
            title: "Maester Cloud",
            items: [
              {
                label: "Hosted Maester Cloud",
                href: "https://maester.cloud",
              },
              {
                label: "Self-hosted Maester Cloud",
                href: "https://maester.cloud",
              },
            ],
          },
        ],
        copyright: `Copyright © ${new Date().getFullYear()} Maester Team`,
      },
      prism: {
        theme: prismThemes.shadesOfPurple,
        darkTheme: prismThemes.shadesOfPurple,
        additionalLanguages: ["powershell"],
      },
      colorMode: {
        defaultMode: "light",
        disableSwitch: false,
        respectPrefersColorScheme: true,
      },
    }),
};

export default config;
