/**
 * Any CSS included here will be global. The classic template
 * bundles Infima by default. Infima is a CSS framework designed to
 * work well for content-centric websites.
 */

/* You can override the default Infima variables here. */
:root {
  --ifm-color-primary: #ba0019;
  --ifm-color-primary-dark: #29784c;
  --ifm-color-primary-darker: #277148;
  --ifm-color-primary-darkest: #205d3b;
  --ifm-color-primary-light: #33925d;
  --ifm-color-primary-lighter: #359962;
  --ifm-color-primary-lightest: #3cad6e;
  --ifm-code-font-size: 95%;
  --docusaurus-highlighted-code-line-bg: rgba(0, 0, 0, 0.1);
}

/* For readability concerns, you should choose a lighter palette in dark mode. */
[data-theme="dark"] {
  /* Coral red — keeps the Maester ember-red feel while remaining legible on
     dark backgrounds. Tuned for >= 5.5:1 contrast on Docusaurus dark canvas
     (#1b1b1d) and the homepage's #050608 surface. */
  --ifm-color-primary: #ff7a7a;
  --ifm-color-primary-dark: #f56565;
  --ifm-color-primary-darker: #ec5757;
  --ifm-color-primary-darkest: #c93f3f;
  --ifm-color-primary-light: #ff9292;
  --ifm-color-primary-lighter: #ffa1a1;
  --ifm-color-primary-lightest: #ffbfbf;
  --ifm-link-color: #ff9292;
  --ifm-link-hover-color: #ffbfbf;
  --docusaurus-highlighted-code-line-bg: rgba(0, 0, 0, 0.3);
}

/* navbar */
.navbar--discord-link {
  width: 32px;
  height: 32px;
  padding: 6px;
  margin-right: 6px;
  margin-left: 6px;
  border-radius: 50%;
  transition: background var(--ifm-transition-fast);
}

.navbar--discord-link:hover {
  background: var(--ifm-color-emphasis-200);
}

