tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

content.content:
@import "tailwindcss";

/* ------------------------------------------------------------------ *
 * Maester Cloud — design tokens
 * Clean, light, modern-minimal SaaS palette (plane.so-inspired),
 * monochrome neutral zinc base + a near-black primary, with semantic
 * security colors. No brand purple.
 * ------------------------------------------------------------------ */
@theme {
  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SFMono-Regular", Menlo, monospace;

  /* surfaces */
  --color-paper: #ffffff;
  --color-canvas: #fafafa;
  --color-subtle: #f4f4f5;

  /* ink */
  --color-ink: #18181b;
  --color-ink-2: #3f3f46;
  --color-ink-3: #71717a;
  --color-line: #e4e4e7;
  --color-line-2: #f0f0f1;

  /* brand primary (monochrome near-black) */
  --color-brand: #111113;
  --color-brand-2: #000000;
  --color-brand-soft: #f4f4f5;
  --color-brand-ink: #18181b;

  /* semantic security */
  --color-pass: #16a34a;
  --color-pass-soft: #dcfce7;
  --color-pass-ink: #15803d;
  --color-fail: #dc2626;
  --color-fail-soft: #fee2e2;
  --color-warn: #d97706;
  --color-warn-soft: #fef3c7;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  background: var(--color-paper);
  color: var(--color-ink);
  font-feature-settings: "cv02", "cv03", "cv04", "cv11";
  font-variant-numeric: tabular-nums;
  overflow-x: clip;
}

img,
svg,
video,
canvas {
  max-width: 100%;
}

::selection {
  background: var(--color-brand-soft);
  color: var(--color-brand-ink);
}

/* Reusable utility classes ----------------------------------------- */
@layer components {
  .container-x {
    width: 100%;
    max-width: 1180px;
    margin-inline: auto;
    padding-inline: 1.5rem;
  }

  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    font-weight: 600;
    font-size: 0.875rem;
    line-height: 1;
    border-radius: 0.625rem;
    padding: 0.7rem 1.05rem;
    border: 1px solid transparent;
    transition: background-color 0.15s, border-color 0.15s, box-shadow 0.15s, color 0.15s, transform 0.15s;
    cursor: pointer;
    max-width: 100%;
    min-height: 2.5rem;
    text-align: center;
    line-height: 1.15;
    white-space: normal;
  }
  .btn-primary {
    background: var(--color-brand);
    color: #fff;
  }
  .btn-primary:hover {
    background: var(--color-brand-2);
  }
  .btn-ghost {
    background: var(--color-paper);
    color: var(--color-ink);
    border-color: var(--color-line);
  }
  .btn-ghost:hover {
    border-color: var(--color-ink-3);
    background: var(--color-canvas);
  }
  .btn-contact {
    background: var(--color-subtle);
    color: var(--color-ink);
    border-color: var(--color-line);
  }
  .btn-contact:hover {
    background: var(--color-line);
    border-color: var(--color-ink-3);
  }
  .pricing-cta:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgb(24 24 27 / 0.12);
  }
  .pricing-cta:active {
    transform: translateY(0);
    box-shadow: none;
  }
  .btn-lg {
    padding: 0.85rem 1.4rem;
    font-size: 0.95rem;
  }

  .raw-report-icon-button {
    display: inline-flex;
    width: 2rem;
    height: 2rem;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--color-line);
    border-radius: 0.5rem;
// @ts-check
import { defineConfig } from 'astro/config';
import tailwindcss from '@tailwindcss/vite';

const baseDomain = process.env.PUBLIC_BASE_DOMAIN || 'maester.cloud';

// https://astro.build/config
export default defineConfig({
  site: `https://${baseDomain}`,
  srcDir: './app',
  vite: {
    plugins: [tailwindcss()],
    server: {
      // Dev-only: the signup API Functions host. In production Azure Static
      // Web Apps routes /api to the linked Functions app on the same origin.
      proxy: {
        '/api': 'http://localhost:7071',
      },
    },
  },
});
app/content.config.ts

