function catalogArgument() {
  const index = process.argv.indexOf("--catalog");
  if (index !== -1) return process.argv[index + 1] ?? "";
  return process.env.MAESTER_TEST_CATALOG ?? "";
}

// Returns the export: { Taxonomy, Frameworks, Tests }. Taxonomy holds the display names of the product,
// feature and area keys and of the ATT&CK techniques that the tests use. Frameworks holds the name of each
// benchmark a suite implements, by the key a test's Benchmark uses.
function loadCatalog() {
  const explicit = catalogArgument();
  if (explicit) {
    const path = resolve(process.cwd(), explicit);
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- path is supplied by the caller (CI workflow or developer)
    if (!existsSync(path)) throw new Error(`Test catalog not found at ${path}. Run build/docs/Export-MtTestCatalogForDocs.ps1 first.`);
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- same caller-supplied path as above
    return JSON.parse(readFileSync(path, "utf8"));
  }

  const result = spawnSync("pwsh", ["-NoProfile", "-NonInteractive", "-File", exporterPath, "-OutputPath", defaultCatalogPath], {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.status === 0 && existsSync(defaultCatalogPath)) {
    return JSON.parse(readFileSync(defaultCatalogPath, "utf8"));
  }
  const reason = result.error ? result.error.message : (result.stderr || result.stdout || "").trim().split("\n").slice(-3).join(" ");
  console.warn(`Could not export the Maester test catalog (${reason || `pwsh exited with ${result.status}`}).`);
  console.warn("Test docs need PowerShell 7 and the Microsoft.Graph.Authentication module to read the native tests.");
  return null;
}

function buildInventory(catalog) {
  const testsById = new Map();
  for (const test of catalog) {
    const key = test.Id.toLowerCase();
    if (testsById.has(key)) continue;
    const testFile = join(repoRoot, test.File);
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- paths come from the exported catalog of repo files
    const help = existsSync(testFile) ? parseCommentHelp(readFileSync(testFile, "utf8")) : {};
    const markdownFile = test.MarkdownPath ? join(repoRoot, test.MarkdownPath) : "";
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- paths come from the exported catalog of repo files
    const markdown = markdownFile && existsSync(markdownFile) ? normalizeMarkdown(stripGeneratedResultPlaceholder(readFileSync(markdownFile, "utf8"))) : "";
    const helpDescription = normalizeMarkdown(help.description ?? "");
    // Tag holds the labels the test's author wrote. LegacyTag holds the tags the test carried in
    // Maester 2.x, which -Tag still matches; they are listed on the tags page and used as search keywords.
    const tags = unique(test.Tag ?? []).sort((a, b) => a.localeCompare(b));
    const legacyTags = unique(test.LegacyTag ?? []).sort((a, b) => a.localeCompare(b));
    const title = titleFor(test);
    const description = markdown ? trimDescription(markdown) : trimDescription(helpDescription || help.synopsis || title);
    const defaultHelpUrl = `https://maester.dev/docs/tests/${test.Id}`;
    testsById.set(key, {
      id: test.Id,
      title,
      description,
      severity: test.Severity || "Unknown",
      suite: suiteFor(test),
      product: productNameFor(test.Product),
      relatedProducts: (test.RelatedProduct ?? []).map(productNameFor),
      feature: featureNameFor(test),
      area: areaNameFor(test.Area),
      resourceType: test.ResourceType ?? "",
      userImpact: test.UserImpact ?? "",
      implementationCost: test.ImplementationCost ?? "",
      mitre: (test.Mitre ?? []).map(mitreLabelFor),
      benchmark: test.Benchmark ?? null,
      controls: test.Control ?? [],
      tags,
      legacyTags,
      services: test.Service ?? [],
      licenses: test.License ?? [],
      permissions: test.Permission ?? [],
      lifecycle: test.Lifecycle || "Stable",
      replacedBy: test.ReplacedBy ?? "",
      longRunning: Boolean(test.LongRunning),
      instanceSource: test.InstanceSource ?? "",
      helpUrl: test.HelpUrl && test.HelpUrl.toLowerCase() !== defaultHelpUrl.toLowerCase() ? test.HelpUrl : "",
      authors: test.Author ?? [],
      contributors: test.Contributor ?? [],
      functionName: test.FunctionName ?? "",
      sourceFunctionFile: test.File,
      sourceMarkdownFile: test.MarkdownPath ?? "",
      synopsis: help.synopsis ?? "",
      helpDescription,
      markdown,
      remediation: extractSection(markdown, /^#{2,6}\s+Remediation action:?$/i),
      relatedLinks: extractSection(markdown, /^#{2,6}\s+Related links?$/i),
      commandLink: commandLinkFor(test.FunctionName ?? "", testFile, docsCommandsRoot),
    });
  }
  return [...testsById.values()].sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
}

function pagePathFor(test) {
  return join(docsTestsRoot, test.suite, `${test.id}.md`);
}

function renderTestPage(test, contributorData) {
  const keywords = unique(["Maester", "Microsoft 365 security", test.id, test.severity, suiteConfig[test.suite]?.label, test.product, test.feature, test.area, ...test.tags, ...test.legacyTags]);
  const body = [];
  body.push(generatedMarker);
  body.push("", `# ${test.id} - ${test.title}`, "");
  body.push(...renderContributorByline(test, contributorData));
function main() {
  const catalog = loadCatalog();
  catalogTests = catalog?.Tests ?? null;
  loadTaxonomyNames(catalog?.Taxonomy);
  loadFrameworkNames(catalog?.Frameworks);
  if (!catalogTests) {
    if (checkMode) {
      console.error("Cannot check the generated test docs without the test catalog.");
      process.exit(1);
    }
    console.warn("Skipping test docs generation; the committed pages in website/docs/tests are used as they are.");
    return;
  }
  const tests = buildInventory(catalogTests);
  const writes = [];
  clearGeneratedDocs();

  const contributorData = computeContributorData(tests, { updateAliases: !checkMode });
  contributorData.profilesById = new Map(contributorData.profiles.map((profile) => [profile.id, profile]));
  // Tests not yet in the released docs version only resolve under /docs/next/.
  const releasedVersions = JSON.parse(readFileSync(join(websiteRoot, "versions.json"), "utf8"));
  const versionedTestsRoot = releasedVersions[0] ? join(websiteRoot, "versioned_docs", `version-${releasedVersions[0]}`, "tests") : "";
  const docPathFor = (test) =>
    versionedTestsRoot && existsSync(join(versionedTestsRoot, test.suite, `${test.id}.md`))
      ? `/docs/tests/${test.id}`
      : `/docs/next/tests/${test.id}`;
  const testTitles = Object.fromEntries(tests.map((test) => [test.id, { title: test.title, path: docPathFor(test) }]));
  writeGenerated(snapshotPath, `${JSON.stringify({ profiles: contributorData.profiles, attributions: contributorData.attributions, tests: testTitles }, null, 2)}\n`, writes);

  writeGenerated(join(docsTestsRoot, "readme.md"), renderRootIndex(tests), writes);
  writeGenerated(join(docsTestsRoot, "tags", "readme.md"), renderTagsIndex(tests), writes);

  for (const suite of Object.keys(suiteConfig)) {
    const suiteTests = tests.filter((test) => test.suite === suite);
    if (suiteTests.length === 0) continue;
    writeGenerated(join(docsTestsRoot, suite, "readme.md"), renderSuiteIndex(suite, suiteTests), writes);
    for (const test of suiteTests) {
      writeGenerated(pagePathFor(test), renderTestPage(test, contributorData), writes);
    }
  }
  if (versionedTestsRoot) relinkVersionedCommandReferences(versionedTestsRoot, writes);

  if (checkMode && writes.length > 0) {
    console.error(`Generated test docs are stale. Run npm run generate-test-docs. Stale files: ${writes.length}`);
    for (const file of writes.slice(0, 20)) console.error(`- ${toPosixPath(relative(repoRoot, file))}`);
    process.exit(1);
  }

  console.log(`${checkMode ? "Checked" : "Generated"} ${tests.length} test documentation pages.`);
}

main();
