function contributorLinkTarget(profile) {
  return profile ? `/contributors/${profile.id.toLowerCase()}` : "/contributors";
}

function renderBylineAvatar(profile, extraClass, roleLabel) {
  if (!profile) return "";
  const title = `${profile.name}${roleLabel ? ` · ${roleLabel}` : ""}`;
  const inner = profile.avatar
    ? `<img src="${jsxAttr(profile.avatar)}" alt="${jsxAttr(profile.name)}" />`
    : `<span className="test-byline-initials">${jsxText(profile.initials ?? "?")}</span>`;
  return `<a className="test-byline-avatar${extraClass}" href="${jsxAttr(contributorLinkTarget(profile))}" title="${jsxAttr(title)}">${inner}</a>`;
}

function renderContributorByline(test, contributorData) {
  const attribution = contributorData?.attributions?.[test.id];
  if (!attribution) return [];
  const profilesById = contributorData.profilesById;
  const author = profilesById.get(attribution.author);
  if (!author) return [];
  const coContributors = attribution.contributors.map((id) => profilesById.get(id)).filter(Boolean);

  const maxAvatars = 6;
  const avatarParts = [renderBylineAvatar(author, " test-byline-avatar--author", "Original author")];
  for (const profile of coContributors.slice(0, maxAvatars - 1)) {
    avatarParts.push(renderBylineAvatar(profile, "", "Co-contributor"));
  }
  const overflow = coContributors.length - (maxAvatars - 1);
  if (overflow > 0) avatarParts.push(`<span className="test-byline-avatar test-byline-more">+${overflow}</span>`);

  const authorLink = `<a href="${jsxAttr(contributorLinkTarget(author))}">${jsxText(author.name)}</a>`;
  let coText = "";
  if (coContributors.length === 1) {
    coText = ` with <a href="${jsxAttr(contributorLinkTarget(coContributors[0]))}">${jsxText(coContributors[0].name)}</a>`;
  } else if (coContributors.length > 1) {
    coText = ` with ${coContributors.length} co-contributors`;
  }

  return [
    `<div className="test-byline">` +
      `<div className="test-byline-avatars">${avatarParts.join("")}</div>` +
      `<div className="test-byline-meta"><span className="test-byline-text">Contributed by ${authorLink}${coText}</span>` +
      `<a className="test-byline-link" href="/contributors">All contributors →</a></div>` +
      `</div>`,
    "",
  ];
}

function normalizeWhitespace(value) {
function renderTestPage(test, contributorData) {
  const keywords = unique(["Maester", "Microsoft 365 security", test.id, test.severity, suiteConfig[test.suite]?.label, test.product, test.feature, test.area, ...test.tags, ...test.legacyTags]);
  const body = [];
  body.push(generatedMarker);
  body.push("", `# ${test.id} - ${test.title}`, "");
  body.push(...renderContributorByline(test, contributorData));
  body.push("## Overview", "", test.markdown || test.helpDescription || test.description, "");
  body.push("## Test Metadata", "");
  body.push("| Field | Value |", "| --- | --- |");
  body.push(`| Test ID | ${escapeTable(test.id)} |`);
  body.push(`| Severity | ${escapeTable(test.severity)} |`);
  body.push(`| Suite | ${escapeTable(suiteConfig[test.suite]?.label ?? test.suite)} |`);
  if (test.product) body.push(`| Product | ${escapeTable(test.product)} |`);
  if (test.relatedProducts.length > 0) body.push(`| Related products | ${escapeTable(test.relatedProducts.join(", "))} |`);
  if (test.feature) body.push(`| Feature | ${escapeTable(test.feature)} |`);
  if (test.area) body.push(`| Area | ${escapeTable(test.area)} |`);
  if (test.resourceType) body.push(`| Resource type | ${escapeTable(test.resourceType)} |`);
  if (test.userImpact) body.push(`| User impact | ${escapeTable(test.userImpact)} |`);
  if (test.implementationCost) body.push(`| Implementation cost | ${escapeTable(test.implementationCost)} |`);
  if (test.mitre.length > 0) body.push(`| MITRE ATT&CK | ${escapeTable(test.mitre.join(", "))} |`);
  if (test.benchmark) {
    const profiles = [test.benchmark.Profile ?? []].flat();
    const upstream = upstreamLabelFor(test.benchmark.Upstream);
    body.push(`| Supports benchmark | ${escapeTable(benchmarkLabelFor(test.benchmark))} |`);
    if (test.benchmark.Level) body.push(`| Benchmark level | ${escapeTable(test.benchmark.Level)} |`);
    if (profiles.length > 0) body.push(`| Benchmark profiles | ${escapeTable(profiles.join(", "))} |`);
    if (test.benchmark.Criticality) body.push(`| Criticality | ${escapeTable(test.benchmark.Criticality)} |`);
    const strategies = [test.benchmark.Strategy ?? []].flat();
    if (strategies.length > 0) body.push(`| Essential Eight strategy | ${escapeTable(strategies.join(", "))} |`);
    if (test.benchmark.Guideline) body.push(`| ISM guideline | ${escapeTable(test.benchmark.Guideline)} |`);
    if (test.benchmark.Section) body.push(`| ISM section | ${escapeTable(test.benchmark.Section)} |`);
    if (upstream) body.push(`| Upstream requirement | ${escapeTable(upstream)} |`);
  }
  if (test.controls.length > 0) body.push(`| Supports controls | ${escapeTable(test.controls.join(", "))} |`);
  if (test.functionName) {
    const commandReference = test.commandLink ? `[${test.functionName}](${test.commandLink})` : `\`${test.functionName}\``;
    body.push(`| PowerShell test | ${commandReference} |`);
  }
  if (test.services.length > 0) body.push(`| Services | ${escapeTable(test.services.join(", "))} |`);
  if (test.licenses.length > 0) body.push(`| Compatible licenses | ${escapeTable(test.licenses.join(", "))} |`);
  if (test.permissions.length > 0) body.push(`| Permissions | ${escapeTable(test.permissions.join(", "))} |`);
  if (test.instanceSource) body.push(`| Runs per instance | Yes, one result per instance from \`${test.instanceSource}\` |`);
  if (test.lifecycle !== "Stable") body.push(`| Lifecycle | ${escapeTable(test.lifecycle)} |`);
  if (test.replacedBy) body.push(`| Replaced by | ${escapeTable(test.replacedBy)} |`);
  if (test.longRunning) body.push("| Long running | Yes |");
  if (test.helpUrl) body.push(`| Learn more | [${escapeTable(test.helpUrl)}](${test.helpUrl}) |`);
  if (test.tags.length > 0) body.push(`| Tags | ${escapeTable(test.tags.join(", "))} |`);
  body.push("");
  if (test.remediation && !test.markdown.includes(test.remediation)) {
    body.push("## Remediation", "", test.remediation, "");
  }
  if (test.relatedLinks && !test.markdown.includes(test.relatedLinks)) {
    body.push("## Related Links", "", test.relatedLinks, "");
  }
  body.push("## Source", "");
  body.push(`- Test: [\`${test.sourceFunctionFile}\`](${sourceUrlFor(test.sourceFunctionFile)})`);
  if (test.sourceMarkdownFile) body.push(`- Documentation: [\`${test.sourceMarkdownFile}\`](${sourceUrlFor(test.sourceMarkdownFile)})`);
  body.push("");

  return `---
title: ${yamlQuote(`${test.id} - ${test.title}`)}
description: ${yamlQuote(test.description)}
slug: /tests/${test.id}
className: generated-test-doc
sidebar_class_name: hidden
hide_table_of_contents: true
keywords:
${keywords.map((keyword) => `  - ${yamlQuote(keyword)}`).join("\n")}
---

${body.join("\n")}`;
}

function renderSuiteIndex(suite, tests) {
