toolUseResult.content:
---
// Page title, plus what the reader needs to know about versions: a test or command that is only in the
// preview says so and shows how to get the preview, whichever channel the reader picked.
import Default from '@astrojs/starlight/components/PageTitle.astro';
import CopyPage from '../CopyPage.astro';
import PreviewOnly from '../PreviewOnly.astro';
import { commandHistory, previewLabel, stableVersion } from '../../lib/versions.mjs';

const { entry, id } = Astro.locals.starlightRoute;
const data = entry.data as Record<string, any>;
const isArchive = id === 'docs/2.x' || id.startsWith('docs/2.x/');
const isDoc = id.startsWith('docs/') && !isArchive;

const commandName = id.match(/^docs\/commands\/([^/]+)$/)?.[1];
const isCommand = Boolean(commandName);
const commandIsPreviewOnly = isCommand && !commandHistory(commandName!);
const test = data.maester?.kind === 'test' ? data.maester : null;
const previewOnly = commandIsPreviewOnly || Boolean(test?.previewOnly) || Boolean(data.since);
const what = test ? 'check' : isCommand ? 'command' : 'page';
const name = test?.id ?? commandName;
---

<div class="mt-title">
	<Default />
	{isDoc && <CopyPage />}
</div>

{
	test && (
		<div class="mt-chips">
			<span class="mt-chip mono">{test.id}</span>
			{test.severity && <span class={`mt-chip mt-sev mt-sev--${test.severity.toLowerCase()}`}>{test.severity}</span>}
			{test.product && <span class="mt-chip">{test.product}</span>}
			{test.feature && <span class="mt-chip">{test.feature}</span>}
			{previewOnly && <span class="mt-chip mt-chip--preview">Preview {previewLabel}</span>}
			{test.previewCheck && <span class="mt-chip mt-chip--check">Runs with -IncludePreview</span>}
		</div>
	)
}

{previewOnly && <PreviewOnly what={what} name={name} />}

{
	test?.previewCheck && (
		<aside class="mt-note">
			<strong>Preview check.</strong> This check is still being tested or depends on a preview API, so it only runs when you
			add <code>-IncludePreview</code>: <code>Invoke-Maester -TestId {test.id} -IncludePreview</code>
		</aside>
	)
}

{
	isDoc && !isCommand && !test && !previewOnly && (
		<aside class="mt-stable-note">
			You're on Maester {stableVersion}. These docs describe the {previewLabel} preview, and differ in places.{' '}
			<a href="/docs/2.x/intro">Read the 2.x docs</a> or <a href="/docs/preview">try the preview</a>.
		</aside>
	)
}

<style>
	.mt-title {
		display: flex;
		align-items: flex-start;
		justify-content: space-between;
		gap: 1rem;
	}
	.mt-chips {
		display: flex;
		flex-wrap: wrap;
		gap: 0.4rem;
		margin-top: 0.75rem;
	}
	.mt-chip {
		display: inline-flex;
		align-items: center;
		border: 1px solid var(--sl-color-gray-5);
		border-radius: 999px;
		padding: 0.1rem 0.6rem;
		font-size: 0.78rem;
		color: var(--sl-color-gray-2);
	}
	.mono {
		font-family: var(--sl-font-mono);
	}
	.mt-sev {
		border-radius: 6px;
		font-weight: 600;
		border: 0;
	}
	.mt-sev--critical {
		background: #fee2e2;
		color: #b91c1c;
	}
	.mt-sev--high {
		background: #ffedd5;
		color: #9a3412;
	}
	.mt-sev--medium {
		background: #fef3c7;
		color: #92400e;
	}
	.mt-sev--low,
	.mt-sev--info {
		background: var(--sl-color-gray-6);
		color: var(--sl-color-gray-2);
	}
	.mt-chip--preview {
		background: var(--mt-warn-soft);
		border-color: var(--mt-warn-line);
		color: var(--mt-warn-ink);
		font-weight: 600;
	}
	.mt-chip--check {
		font-family: var(--sl-font-mono);
		font-size: 0.72rem;
	}
	.mt-note {
		margin-top: 1rem;
		border: 1px solid var(--sl-color-gray-5);
		border-radius: var(--mt-radius);
		padding: 0.75rem 1rem;
		font-size: 0.9rem;
	}
	.mt-stable-note {
		display: none;
		margin-top: 1rem;
		border-left: 3px solid var(--mt-warn);
		background: var(--mt-warn-soft);
		border-radius: 8px;
		padding: 0.6rem 0.9rem;
		font-size: 0.875rem;
	}
	:global(:root[data-channel='stable']) .mt-stable-note {
		display: block;
	}
</style>

---
// Shown on any test, command or guide that only the preview has: what that means, and how to get the preview.
import { previewLabel, previewVersion, stableVersion } from '../lib/versions.mjs';

interface Props {
	what: 'check' | 'command' | 'page';
	name?: string;
}
const { what, name } = Astro.props;
const subject = what === 'page' ? 'This feature' : name ? `${name}` : `This ${what}`;
---

<aside class="mt-preview" aria-label="Only in the preview">
	<div class="mt-preview__head">
		<span class="mt-preview__badge">Preview {previewLabel}</span>
		<strong>Only in the preview</strong>
	</div>
	<p>
		{subject} is in Maester {previewVersion} and not in the stable {stableVersion} release yet. It will be in the next stable
		release. To use it now, install the preview:
	</p>
	<pre><code>Install-Module Maester -AllowPrerelease -Force</code></pre>
	<p class="mt-preview__links">
		<a href="/docs/preview">How to get the preview, and go back</a>
		<a href="/docs/preview#github-actions">Use the preview in GitHub Actions</a>
	</p>
</aside>

<style>
	.mt-preview {
		margin-top: 1rem;
		border: 1px solid var(--mt-warn-line);
		background: var(--mt-warn-soft);
		border-radius: var(--mt-radius);
		padding: 0.9rem 1.1rem;
		font-size: 0.92rem;
	}
	.mt-preview__head {
		display: flex;
		align-items: center;
		gap: 0.6rem;
		color: var(--sl-color-white);
	}
	.mt-preview__badge {
		font-family: var(--sl-font-mono);
		font-size: 0.7rem;
		font-weight: 600;
		border-radius: 6px;
		padding: 0.1rem 0.45rem;
		background: var(--mt-warn);
		color: #fff;
	}
	p {
		margin: 0.5rem 0 0;
		color: var(--sl-color-gray-2);
	}
	pre {
		margin: 0.6rem 0 0;
		padding: 0.5rem 0.8rem;
		border-radius: 8px;
		background: var(--sl-color-gray-6);
		border: 1px solid var(--sl-color-gray-5);
		font-size: 0.82rem;
		overflow-x: auto;
	}
	.mt-preview__links {
		display: flex;
		gap: 1.25rem;
		flex-wrap: wrap;
		font-weight: 600;
		font-size: 0.85rem;
	}
</style>

---
// "Copy page" for AI tools: the page as Markdown, or a question about it in ChatGPT or Claude.
const path = Astro.url.pathname.replace(/\/$/, '');
const mdPath = `${path}.md`;
const pageUrl = new URL(path, Astro.site).href;
const prompt = encodeURIComponent(`Read ${pageUrl} and help me with Maester.`);
---

<mt-copy-page class="mt-copy" data-md={mdPath}>
	<button type="button" class="mt-copy__main">
		<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"></rect><path d="M5 15V5a2 2 0 0 1 2-2h10"></path></svg>
		<span class="mt-copy__label">Copy page</span>
	</button>
	<details>
		<summary aria-label="More ways to use this page with AI"
			><svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M2 3.5 5 6.5 8 3.5" fill="none" stroke="currentColor" stroke-width="1.5"></path></svg></summary
		>
		<div class="mt-copy__menu">
			<a href={mdPath}>View as Markdown</a>
			<a href={`https://chatgpt.com/?hints=search&q=${prompt}`} target="_blank" rel="noopener">Open in ChatGPT</a>
			<a href={`https://claude.ai/new?q=${prompt}`} target="_blank" rel="noopener">Open in Claude</a>
			<a href="/llms.txt">llms.txt for the whole site</a>
		</div>
	</details>
</mt-copy-page>

<script>
	class CopyPage extends HTMLElement {
		connectedCallback() {
			const button = this.querySelector<HTMLButtonElement>('.mt-copy__main');
			const label = this.querySelector('.mt-copy__label');
			button?.addEventListener('click', async () => {
				try {
					const response = await fetch(this.dataset.md ?? '');
					await navigator.clipboard.writeText(await response.text());
					if (label) label.textContent = 'Copied';
				} catch {
					if (label) label.textContent = 'Could not copy';
				}
				setTimeout(() => label && (label.textContent = 'Copy page'), 2000);
			});
		}
	}
	customElements.define('mt-copy-page', CopyPage);
</script>

<style>
	.mt-copy {
		position: relative;
		display: inline-flex;
		margin-top: 1.1rem;
		flex: none;
		border: 1px solid var(--sl-color-gray-5);
		border-radius: 9px;
		font-size: 0.8125rem;
	}
	.mt-copy__main,
	summary {
		display: inline-flex;
		align-items: center;
		gap: 0.4rem;
		background: none;
		border: 0;
		color: var(--sl-color-white);
		font: inherit;
		font-weight: 600;
		padding: 0.35rem 0.65rem;
		cursor: pointer;
	}
	summary {
		list-style: none;
		border-inline-start: 1px solid var(--sl-color-gray-5);
		height: 100%;
	}
	summary::-webkit-details-marker {
		display: none;
	}
	.mt-copy__menu {
		position: absolute;
		right: 0;
		top: calc(100% + 6px);
		z-index: 20;
		min-width: 15rem;
		display: flex;
		flex-direction: column;
		background: var(--sl-color-black);
		border: 1px solid var(--sl-color-gray-5);
		border-radius: 12px;
		padding: 0.35rem;
		box-shadow: 0 18px 40px -20px rgba(0, 0, 0, 0.45);
	}
	.mt-copy__menu a {
		padding: 0.5rem 0.7rem;
		border-radius: 8px;
		color: var(--sl-color-white);
		text-decoration: none;
	}
	.mt-copy__menu a:hover {
		background: var(--sl-color-gray-6);
	}
	@media (max-width: 50rem) {
		.mt-copy {
			display: none;
		}
	}
</style>

