import React from "react";
import Layout from "@theme/Layout";
import Link from "@docusaurus/Link";
import TestBuilder from "@site/src/components/TestBuilder";

export default function TestBuilderPage() {
  return (
    <Layout title="Test builder" description="Pick the attributes of a Maester test, with the rubric for each one, and get the code.">
      <main style={{ maxWidth: 1440, margin: "0 auto", padding: "2.5rem 1.25rem 4rem" }}>
        <header style={{ maxWidth: "46rem", marginBottom: "2rem" }}>
          <h1>Test builder</h1>
          <p>
            Every Maester test declares what it is about, how urgent a failure is and what it needs to run, in a <code>[MaesterTest()]</code> attribute. Pick the values here. Each field explains what it means and shows the rule reviewers apply, and the code updates as you go.
          </p>
          <p>
            The lists and rules on this page are generated from the files Maester itself uses, so they match what the unit tests and the review step enforce. The full text is in the <Link to="/docs/next/writing-tests/attribute-rubric">attribute rubric</Link>.
          </p>
        </header>
        <TestBuilder />
      </main>
    </Layout>
  );
}
import React from "react";
import Layout from "@theme/Layout";
import EidscaSync from "@site/src/components/EidscaSync";

export default function EidscaSyncPage() {
  return (
    <Layout
      title="EIDSCA sync"
      description="How the Maester EIDSCA tests are generated from the Entra ID Security Config Analyzer, and a live comparison with it."
    >
      <main style={{ maxWidth: 1440, margin: "0 auto", padding: "2.5rem 1.25rem 4rem" }}>
        <header style={{ maxWidth: "46rem", marginBottom: "2rem" }}>
          <h1>EIDSCA sync</h1>
          <p>
            The EIDSCA tests in Maester are generated from the Entra ID Security Config Analyzer (EIDSCA). This page
            shows which values come from EIDSCA and which Maester adds, and compares Maester with the latest EIDSCA
            config.
          </p>
        </header>
        <EidscaSync />
      </main>
    </Layout>
  );
}
// Registers a static route for every contributor: /contributors/<github-handle>
// (lowercased). Data comes from the generated snapshot at src/data/contributors.json.
const path = require("path");

module.exports = function contributorPagesPlugin() {
  return {
    name: "contributor-pages",
    async contentLoaded({ actions }) {
      const { addRoute, createData } = actions;
      // Resolve at call time so a regenerated snapshot is picked up on restart.
      const dataPath = path.join(__dirname, "..", "data", "contributors.json");
      delete require.cache[require.resolve(dataPath)];
      const { profiles } = require(dataPath);
      for (const profile of profiles) {
        const idModule = await createData(`contributor-${profile.id.toLowerCase()}.json`, JSON.stringify(profile.id));
        addRoute({
          path: `/contributors/${profile.id.toLowerCase()}`,
          component: "@site/src/components/ContributorPage/index.js",
          exact: true,
          modules: { contributorId: idModule },
        });
      }
    },
  };
};
import React from "react";
import Layout from "@theme/Layout";
import Link from "@docusaurus/Link";
import { useDocsData } from "@docusaurus/plugin-content-docs/client";
import contributorData from "@site/src/data/contributors.json";
import { MvpBadge, SocialLinks } from "@site/src/pages/contributors";
import styles from "./styles.module.css";

function TestList({ title, testIds }) {
  // contributors.json can list a test before its generated page is committed (a build without PowerShell uses
  // the committed pages), so link only to pages this build has.
  const docPaths = new Set(useDocsData(undefined).versions.flatMap((version) => version.docs.map((doc) => doc.path)));
  if (testIds.length === 0) return null;
  return (
    <section className={styles.section}>
      <h2>{title}</h2>
      <ul className={styles.testList}>
        {testIds.map((id) => {
          const path = contributorData.tests?.[id]?.path ?? `/docs/tests/${id}`;
          const content = (
            <>
              <span className={styles.testId}>{id}</span>
              <span className={styles.testTitle}>{contributorData.tests?.[id]?.title ?? ""}</span>
            </>
          );
          return (
            <li key={id}>
              {docPaths.has(path) ? <Link to={path}>{content}</Link> : <span className={styles.testRow}>{content}</span>}
            </li>
          );
        })}
      </ul>
    </section>
  );
