---
// A HyperFrames explainer, played live: the composition in public/explainers/<slug>/ runs in the HyperFrames
// player, with chapters to jump to and the full transcript as text (for search engines, screen readers and
// anyone who prefers to read). It never plays on its own; with reduced motion the transcript opens instead.
import explainers from '../data/explainers.json';

interface Props {
	slug: keyof typeof explainers;
	/** Show the title above the player. */
	heading?: boolean;
}
const { slug, heading = true } = Astro.props;
const e = explainers[slug];
const time = (t: number) => `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`;
const videoLd = {
	'@context': 'https://schema.org',
	'@type': 'VideoObject',
	name: e.title,
	description: e.chapters.map((c) => c.text).join(' '),
	uploadDate: e.updated,
	duration: `PT${e.duration}S`,
	embedUrl: new URL(`/explainers/${slug}/index.html`, Astro.site).href,
	thumbnailUrl: new URL('/img/maester-social-card.jpg', Astro.site).href,
};
---

<mt-explainer class="mt-ex not-content" data-slug={slug}>
	{heading && <p class="mt-ex__title">{e.title} <span>· {time(e.duration)}</span></p>}
	<div class="mt-ex__frame">
		<hyperframes-player src={`/explainers/${slug}/index.html`} width="1920" height="1080" controls></hyperframes-player>
	</div>
	<ol class="mt-ex__chapters">
		{
			e.chapters.map((c) => (
				<li>
					<button type="button" data-t={c.t}>
						<span class="mt-ex__t">{time(c.t)}</span>
						{c.title}
					</button>
				</li>
			))
		}
	</ol>
	<details class="mt-ex__transcript">
		<summary>Transcript</summary>
		{
			e.chapters.map((c) => (
				<p>
					<strong>{c.title}.</strong> {c.text}
				</p>
			))
		}
		<p class="mt-ex__meta">Updated {e.updated} for Maester {e.for}. Made with HyperFrames from HTML in the Maester repository.</p>
	</details>
	<script type="application/ld+json" set:html={JSON.stringify(videoLd)} />
</mt-explainer>

<script>
	import '@hyperframes/player';

	class Explainer extends HTMLElement {
		connectedCallback() {
			const player = this.querySelector('hyperframes-player') as (HTMLElement & { seek(t: number): void; play(): void }) | null;
			for (const button of this.querySelectorAll<HTMLButtonElement>('button[data-t]')) {
				button.addEventListener('click', () => {
					player?.seek(Number(button.dataset.t));
					player?.play();
				});
			}
			if (matchMedia('(prefers-reduced-motion: reduce)').matches) this.querySelector('details')?.setAttribute('open', '');
		}
	}
	customElements.define('mt-explainer', Explainer);
</script>

<style>
	.mt-ex {
		display: block;
		margin: 1.5rem 0;
	}
	.mt-ex__title {
		font-weight: 650;
		margin: 0 0 0.6rem;
	}
	.mt-ex__title span {
		color: var(--sl-color-gray-3);
		font-weight: 400;
	}
	.mt-ex__frame {
		aspect-ratio: 16 / 9;
		border-radius: 16px;
		overflow: hidden;
		background: #09090b;
		border: 1px solid var(--sl-color-gray-5);
