# The test builder page on maester.dev reads website/src/data/test-builder.json, which is generated from the
# schema, the registries and the rubric. This test fails when one of those changed and the file was not regenerated.
Describe 'Test builder data' {
    It 'has the Id and Control patterns of the schema written out in its code' {
        $root = (Resolve-Path "$PSScriptRoot/../../..").Path
        $schema = Import-PowerShellDataFile (Join-Path $root 'powershell/assets/MaesterTestSchema.psd1')
        $code = Get-Content (Join-Path $root 'website/src/components/TestBuilder/generate.js') -Raw
        $code | Should -Match ([regex]::Escape("const ID_PATTERN = /$($schema.IdPattern)/;"))
        $code | Should -Match ([regex]::Escape("const CONTROL_PATTERN = /$($schema.Properties.Control.Pattern)/;"))
    }

    It 'is up to date with the schema, the registries and the rubric' {
powershell/tests/general/TestBuilderData.Tests.ps1:7:        $code = Get-Content (Join-Path $root 'website/src/components/TestBuilder/generate.js') -Raw
        @($script:exported['MT.1001'].Control | Where-Object { $_ -notlike 'nist-800-53-r5:*' }).Count | Should -Be 0
        @($script:exported['AD-CFG-02'].Control).Count | Should -Be 0
    }

    It 'Gives the level of every CIS test, which the generated title shows as (L1) or (L2)' {
        $cis = @($script:export.Tests | Where-Object { $_.Id -like 'CIS.*' })
        $cis.Count | Should -Be 148
        @($cis | Where-Object { $_.Benchmark.Level -cnotmatch '^L[12]$' } | ForEach-Object Id) | Should -BeNullOrEmpty
        $generator = Get-Content -LiteralPath (Join-Path $script:repoRoot 'website/scripts/generate-test-docs.mjs') -Raw
        $generator | Should -Match 'test\.Benchmark\?\.Level' -Because 'the title prefix comes from Benchmark'
        $generator | Should -Not -Match 'titleFor\(test, legacyTags\)' -Because 'the title no longer reads the Maester 2.x tags'
    }
}

