2	// A HyperFrames explainer, played live: the composition in public/explainers/<slug>/ runs in the HyperFrames
3	// player, with chapters to jump to and the full transcript as text (for search engines, screen readers and
4	// anyone who prefers to read).
5	//
6	// With `autoplay`, it starts playing muted when it scrolls into view, shows the voice-over as captions, and offers
7	// one click to hear it with sound from the start. It pauses again when it scrolls away, and never starts by
8	// itself for someone who prefers reduced motion. Without `autoplay` it waits behind a large play button.
9	import explainers from '../data/explainers.json';
10	
11	interface Props {
12		slug: keyof typeof explainers;
13		/** Show the title above the player. */
14		heading?: boolean;
15		/** Play muted, with captions, when it comes into view. */
16		autoplay?: boolean;
17	}
18	const { slug, heading = true, autoplay = false } = Astro.props;
19	const e = explainers[slug];
20	const time = (t: number) => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}`;
21	const hasSound = e.chapters.some((c) => 'length' in c);
22	const cues = e.chapters.map((c, i) => ({
23		t: c.t,
24		end: 'length' in c ? c.t + (c as { length: number }).length + 0.3 : (e.chapters[i + 1]?.t ?? e.duration),
25		text: c.text,
26	}));
