81		type Player = HTMLElement & { seek(t: number): void; play(): void; pause(): void; muted: boolean; currentTime: number; paused: boolean };
82	
83		// The player (and the composition it loads) is fetched only when the explainer comes near the screen.
84		const load = () => import('@hyperframes/player').then(() => customElements.whenDefined('hyperframes-player'));
85		const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
86	
87		class Explainer extends HTMLElement {
