94				const autoplay = this.hasAttribute('data-autoplay') && !reducedMotion;
95				// Muted autoplay until the viewer asks for sound or takes control; then the explainer is theirs.
96				let preview = false;
97	
98				const playWithSound = async (at = 0) => {
99					await load();
100					preview = false;
101					player.muted = false;
102					start.hidden = true;
103					if (sound) sound.hidden = true;
104					caption.hidden = true;
105					player.seek(at);
106					player.play();
107				};
108	
109				const showCaption = () => {
