124				const near = new IntersectionObserver(
125					(entries) => {
126						if (entries.some((entry) => entry.isIntersecting)) {
127							near.disconnect();
128							load();
129						}
130					},
131					{ rootMargin: '600px' },
132				);
133				near.observe(this);
134	
135				if (autoplay) {
