const out = process.argv[2];
const browser = await chromium.launch({ args: ['--autoplay-policy=document-user-activation-required'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
await page.goto('http://localhost:4329/', { waitUntil: 'networkidle' });
await page.locator('#how-it-works .mt-ex__frame').scrollIntoViewIfNeeded();
const state = () => page.evaluate(() => {
  const ex = document.querySelector('#how-it-works mt-explainer');
  const p = ex.querySelector('hyperframes-player');
  return { start: ex.querySelector('[data-start]').hidden, sound: !ex.querySelector('[data-sound]').hidden,
    caption: ex.querySelector('[data-caption]').hidden ? null : ex.querySelector('[data-caption]').textContent,
    t: p.currentTime, paused: p.paused, muted: p.muted };
});
await page.waitForTimeout(6000);
console.log('in view 6s', await state());
await page.screenshot({ path: `${out}/autoplay.png` });
await page.evaluate(() => window.scrollTo(0, 0));
await page.waitForTimeout(1500);
console.log('scrolled away', await state());
await page.locator('#how-it-works .mt-ex__frame').scrollIntoViewIfNeeded();
await page.waitForTimeout(2000);
console.log('back in view', await state());
await page.click('#how-it-works [data-sound]');
await page.waitForTimeout(3000);
const audio = await page.evaluate(() => {
  const f = document.querySelector('#how-it-works hyperframes-player').shadowRoot?.querySelector('iframe');
  const a = f?.contentDocument?.querySelector('audio');
  return a ? { paused: a.paused, muted: a.muted, t: a.currentTime } : 'no audio element reachable';
});
console.log('after sound click', await state(), audio);
await page.evaluate(() => window.scrollTo(0, 0));
await page.waitForTimeout(1500);
console.log('scrolled away after sound', await state());
console.log('errors', errors);
await browser.close();
EOF
