		border: 0;
		outline: 0;
		background: transparent;
		color: var(--sl-color-white);
		font: inherit;
		font-size: 0.875rem;
	}

	/* The menus */
	.mt-pick {
		position: relative;
	}
	.mt-pick__trigger {
		display: inline-flex;
		align-items: center;
		gap: 0.5rem;
		height: 2.5rem;
		max-width: 20rem;
		border: 1px solid var(--sl-color-gray-5);
		border-radius: 9px;
		background: var(--sl-color-black);
		color: var(--sl-color-gray-2);
		font: inherit;
		font-size: 0.875rem;
		padding-inline: 0.75rem 0.65rem;
		cursor: pointer;
	}
	.mt-pick__trigger:hover,
	.mt-pick__trigger[aria-expanded='true'] {
		border-color: var(--sl-color-gray-3);
	}
	.mt-pick.is-set .mt-pick__trigger {
		color: var(--sl-color-white);
		border-color: var(--sl-color-accent);
		background: color-mix(in srgb, var(--sl-color-accent) 8%, var(--sl-color-black));
	}
