		margin: -0.2rem 0.15rem 0 0.15rem;
		border-right: 1.5px solid currentColor;
		border-bottom: 1.5px solid currentColor;
		transform: rotate(45deg);
		opacity: 0.6;
		transition: transform 0.2s ease;
	}
	.mt-pick__trigger[aria-expanded='true'] .mt-pick__chev {
		transform: translateY(0.2rem) rotate(225deg);
	}
	.mt-pick__panel {
		position: absolute;
		z-index: 20;
		top: calc(100% + 6px);
		left: 0;
		width: min(24rem, calc(100vw - 24px));
		display: flex;
		flex-direction: column;
		border: 1px solid var(--sl-color-gray-5);
		border-radius: 12px;
		background: var(--sl-color-black);
		box-shadow: 0 20px 40px -12px rgba(0, 0, 0, 0.35);
		overflow: hidden;
		animation: mt-pick-in 0.16s ease-out;
	}
	.mt-pick__panel[hidden] {
		display: none;
	}
	.mt-pick__panel--narrow {
		width: min(18rem, calc(100vw - 24px));
	}
	@keyframes mt-pick-in {
		from {
			opacity: 0;
			transform: translateY(-4px);
		}
	}
	.mt-pick__find {
		display: flex;
		align-items: center;
		gap: 0.5rem;
		padding: 0.6rem 0.75rem;
		border-bottom: 1px solid var(--sl-color-gray-6);
		color: var(--sl-color-gray-3);
	}
	.mt-pick__list,
	.mt-pick__children {
		list-style: none;
		margin: 0;
