		max-height: min(22rem, 55vh);
		overflow-y: auto;
		padding: 0.35rem;
	}
	.mt-pick__list li {
		margin: 0;
	}
	.mt-pick__list [hidden] {
		display: none;
	}
	.mt-pick__row {
		display: flex;
		align-items: center;
	}
	.mt-pick__twisty {
		display: grid;
		place-items: center;
		width: 1.5rem;
		height: 1.75rem;
		flex: none;
		border: 0;
