		border-radius: 7px;
		font-size: 0.85rem;
		color: var(--sl-color-gray-2);
		cursor: pointer;
	}
	.mt-pick__item:hover,
	.mt-pick__item:focus-within {
		background: var(--sl-color-gray-6);
		color: var(--sl-color-white);
	}
	.mt-pick__item img {
		width: 16px;
		height: 16px;
		flex: none;
		object-fit: contain;
	}
	.mt-pick__item input,
	.mt-cat td input {
		flex: none;
		width: 15px;
		height: 15px;
		margin: 0;
		accent-color: var(--sl-color-accent);
