import { chromium } from '$PWD/node_modules/playwright/index.mjs';
const S = '$S';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
const errors = []; page.on('pageerror', (e) => errors.push(String(e))); page.on('console', m => m.type()==='error' && errors.push(m.text()));
await page.goto('http://localhost:4329/docs/tests', { waitUntil: 'networkidle' });
const info = () => page.evaluate(() => ({ cmd: document.querySelector('[data-cmd]').textContent, count: document.querySelector('[data-count]').textContent, url: location.search, labels: [...document.querySelectorAll('[data-label]')].map(l => l.textContent) }));
console.log('wrapped product cells', await page.evaluate(() => [...document.querySelectorAll('td.mt-cat__product')].filter(td => td.getClientRects()[0]?.height > 30).length));
await page.screenshot({ path: S + '/cat-top.png', clip: { x: 0, y: 150, width: 1440, height: 700 } });
await page.click('[data-pick=product] .mt-pick__trigger');
await page.keyboard.type('conditional');
await page.waitForTimeout(200);
await page.screenshot({ path: S + '/cat-tree-search.png', clip: { x: 0, y: 150, width: 1440, height: 700 } });
await page.check('input[data-feature="entra/conditional-access"]');
console.log('feature', await info());
await page.fill('[data-pick=product] [data-find]', '');
await page.check('input[data-product="intune"]');
await page.click('[data-pick=product] .mt-pick__twisty[aria-label="Features of Entra ID"]');
await page.waitForTimeout(200);
await page.screenshot({ path: S + '/cat-tree.png', clip: { x: 0, y: 150, width: 1440, height: 800 } });
console.log('+intune', await info());
await page.click('[data-pick=product] [data-done]');
await page.click('[data-toggle=severity][data-value=High]');
await page.click('[data-pick=area] .mt-pick__trigger');
await page.check('input[data-area="authentication"]');
await page.keyboard.press('Escape');
console.log('+high +auth', await info());
await page.screenshot({ path: S + '/cat-filtered.png', clip: { x: 0, y: 150, width: 1440, height: 700 } });
const url = page.url();
await page.goto(url, { waitUntil: 'networkidle' });
console.log('reloaded', await info());
await page.click('.mt-cat__reset');
console.log('reset', await info());
await page.goto('http://localhost:4329/docs/tests?product=entra&suite=CIS', { waitUntil: 'networkidle' });
console.log('old link', await info());
await page.goto('http://localhost:4329/test-builder', { waitUntil: 'networkidle' });
console.log('builder', await page.evaluate(() => ({ h1: document.querySelector('h1')?.textContent, sidebar: !!document.querySelector('#starlight__sidebar, nav.sidebar, .sidebar-pane'), current: document.querySelector('[aria-current="page"]')?.textContent?.trim(), tab: [...document.querySelectorAll('header a')].find(a => a.getAttribute('aria-current'))?.textContent?.trim(), overflow: document.documentElement.scrollWidth > innerWidth })));
await page.screenshot({ path: S + '/builder.png' });
console.log('errors', errors);
await browser.close();
EOF
node $S/catalog.mjs

