72	// Every personal address becomes a demo persona; addresses that name a role or a test object stay.
73	const personas = ['alex.wilber', 'lee.gu', 'nestor.wilke', 'megan.bowen', 'isaiah.langer', 'diego.siciliani', 'lidia.holloway', 'lynne.robbins', 'miriam.graham', 'johanna.lorenz', 'joni.sherman', 'pradeep.gupta', 'patti.fernandez', 'christie.cline', 'grady.archie', 'henrietta.mueller'];
