75	const addresses = new Map();
76	json = json.replace(/\b([A-Za-z0-9._#-]+)@(contoso(?:\.mail)?(?:\.onmicrosoft)?\.com)\b/g, (match, local, domain) => {
77		if (roleAddress.test(local)) return match;
