	* the pages configured in the `items` array is the current page.
	*/
	items: z.any().array()
});
const StarlightSidebarTopicsConfigSchema = z.union([sidebarTopicGroupSchema, sidebarTopicLinkSchema]).array();
const StarlightSidebarTopicsOptionsSchema = z.strictObject({
	/**
