	.post__authors {
		display: flex;
		flex-wrap: wrap;
		gap: 1rem 2rem;
		margin: 2rem 0 0;
		padding: 1.5rem 0 0;
		border-top: 1px solid var(--sl-color-gray-5);
		list-style: none;
