const decode = (text: string) => text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
const commands = (await getCollection('docs', (e) => /^docs\/commands\/[^/]+$/.test(e.id)))
	.map((e) => ({ name: e.id.split('/').pop()!, description: decode(e.data.description ?? ''), previewOnly: !commandHistory(e.id.split('/').pop()!) }))
	.sort((a, b) => a.name.localeCompare(b.name));
